mapper.select:
SELECT id
FROM sku
WHERE erp_code = #{erpCode}

SELECT id
FROM sensitive_attribute
WHERE en_name = #{enName}

SELECT poc.id, poc.sku_id AS skuId, poc.create_time AS createTime
FROM platform_order_content poc
JOIN sku s ON s.erp_code = poc.sku_id
WHERE poc.create_time >= #{cutoff} AND poc.create_time <= #{upper}
  AND poc.sku_id NOT LIKE '1%'
  AND poc.sku_id <> s.id

  AND (poc.create_time > #{afterTime}
       OR (poc.create_time = #{afterTime} AND poc.id > #{afterId}))

ORDER BY poc.create_time, poc.id
LIMIT #{limit}
